import numpy as np
import pandas as pd

def r_pluck(x, *args, **kwargs):
    """
    Reproduces purrr::pluck in Python.

    x: The object to pluck from (list, dict, or pandas DataFrame/Series).
    *args: The indices/names to pluck.
    kwargs: contains .default (since .default is not a valid Python variable name).
    """
    # Handle .default from kwargs since it's not a valid Python parameter name
    default = kwargs.get('.default', None)
    curr = x

    for arg in args:
        # In R, pluck is designed for lists (represented here as dicts or lists).

        # Case 1: curr is a dict (R's named list representation)
        if isinstance(curr, dict):
            if arg in curr:
                curr = curr[arg]
            else:
                # R allows numeric indexing on named lists (1-based)
                try:
                    # Treat the dict as a sequence for positional indexing
                    idx = int(arg) - 1
                    values = list(curr.values())
                    if 0 <= idx < len(values):
                        curr = values[idx]
                    else:
                        return default
                except (ValueError, TypeError):
                    return default

        # Case 2: curr is a list or numpy array (R's unnamed list or vector)
        elif isinstance(curr, (list, np.ndarray)):
            try:
                # R's pluck is 1-indexed for numeric arguments
                if isinstance(arg, (int, float, np.integer)):
                    idx = int(arg) - 1
                    if 0 <= idx < len(curr):
                        curr = curr[idx]
                    else:
                        return default
                else:
                    # Cannot pluck a non-dict by name
                    return default
            except (IndexError, TypeError, ValueError):
                return default

        # Case 3: pandas DataFrame or Series (R's data frame/column)
        elif isinstance(curr, (pd.DataFrame, pd.Series)):
            try:
                if isinstance(arg, (int, float, np.integer)):
                    idx = int(arg) - 1
                    if isinstance(curr, pd.Series):
                        curr = curr.iloc[idx]
                    else: # DataFrame
                        # Plucking from a DF usually refers to columns
                        curr = curr.iloc[:, idx]
                elif isinstance(arg, str):
                    if isinstance(curr, pd.Series):
                        curr = curr.loc[arg]
                    else: # DataFrame
                        curr = curr[arg]
                else:
                    return default
            except (IndexError, KeyError, TypeError):
                return default

        # Case 4: Scalar or other types
        else:
            return default

    return curr
